package dev.phpruntime.runtime;

import com.oracle.truffle.api.CompilerDirectives.TruffleBoundary;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Parameter names, by-reference positions and the variadic position of the methods
 * of the classes implemented in Java, as php declares them. Generated by
 * {@code scripts/internal-param-names/gen.php} into {@code class-params.tsv}; loaded
 * when a builtin class is first linked, so startup does no work.
 */
public final class InternalParamNames {

    /** The parameters of one Java-implemented method. {@code variadicIndex} is -1 when none. */
    public record Params(List<String> names, int variadicIndex, long refMask) {
    }

    private static volatile Map<String, Params> table;

    private InternalParamNames() {
    }

    /** The parameters of {@code Class::method}, or null when php has no such method. */
    @TruffleBoundary
    public static Params forMethod(String className, String methodName) {
        Map<String, Params> t = table;
        if (t == null) {
            t = load();
            table = t;
        }
        return t.get(key(className, methodName));
    }

    private static String key(String className, String methodName) {
        return PhpStrings.lower(className) + "::" + PhpStrings.lower(methodName);
    }

    @TruffleBoundary
    private static Map<String, Params> load() {
        Map<String, Params> out = new HashMap<>();
        try (InputStream in = InternalParamNames.class.getResourceAsStream(
                "/dev/phpruntime/class-params.tsv")) {
            if (in == null) {
                return out;
            }
            BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.isEmpty() || line.charAt(0) == '#') {
                    continue;
                }
                String[] fields = line.split("\t", -1);
                List<String> names = new ArrayList<>(fields.length - 1);
                int variadic = -1;
                long refMask = 0;
                for (int i = 1; i < fields.length; i++) {
                    String field = fields[i];
                    int first = field.indexOf(':');
                    int second = field.indexOf(':', first + 1);
                    names.add(field.substring(0, first));
                    if (field.charAt(first + 1) == '1' && i <= 64) {
                        refMask |= 1L << (i - 1);
                    }
                    if (field.charAt(second + 1) == '1') {
                        variadic = i - 1;
                    }
                }
                int sep = fields[0].indexOf("::");
                if (sep < 0) {
                    continue;
                }
                out.put(key(fields[0].substring(0, sep), fields[0].substring(sep + 2)),
                        new Params(List.copyOf(names), variadic, refMask));
            }
        } catch (IOException e) {
            throw new IllegalStateException("cannot read method parameter lists", e);
        }
        return Map.copyOf(out);
    }
}
